// DeleteUniqueIndexCache 删除索引存在的缓存
func (s *SysOperationLogRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.SysOperationLog) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, s.cache.Key(CacheSysOperationLogByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[s.cache.Key(CacheSysOperationLogByIDPrefix, item.ID)] = struct{}{}
			KeyMap[s.cache.Key(CacheSysOperationLogByAdminIDPrefix, item.AdminID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := s.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
